bib=[]
for x in refs:
 fields=[f'  author = {{{x["author"]}}}',f'  title = {{{x["title"]}}}',f'  url = {{{x["url"]}}}',f'  note = {{{x["status"]}}}',f'  annote = {{{x["verification_scope"]} Exact locator: {x["exact_locator"]}}}']
 if x['year']: fields.insert(2,f'  year = {{{x["year"]}}}')
 if x['extra']:fields.append('  '+x['extra'])
 bib.append('@'+x['kind']+'{'+x['key']+',\n'+',\n'.join(fields)+'\n}')
(B/'references.bib').write_text('\n\n'.join(bib)+'\n')
tsv('reference_ledger.tsv',['key','url','status','verification_scope','exact_locator'],[{k:x[k] for k in ['key','url','status','verification_scope','exact_locator']} for x in refs])
(B/'reference_records.json').write_text(json.dumps(refs,indent=2,ensure_ascii=False)+'\n')
print(f'{len(readings)} scan alarms; {len(refs)} bibliography records')
